pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Restrict value to avoid out-of-gas or excessive balance
        vm.assume(value <= address(c).balance);
        // Send money
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value, data));
        if (ok) {
