pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Bound value to avoid overflow issues (e.g., sum of balances fits in uint256)
        vm.assume(value <= address(this).balance / 2);
        // Ensure target is not the contract itself to avoid reentrancy complications
        vm.assume(target != address(c));
        // Ensure owner is not the zero address
        vm.assume(c.owner() != address(0));

        // Provide some ether to the contract via fallback
        vm.deal(address(c), 1 ether);

        // Call sendMoney as owner
        vm.prank(c.owner());
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        vm.assume(success);

        uint256 balanceBefore = address(c).balance;

        // Owner calls withdrawAll
        vm.prank(c.owner());
        c.withdrawAll();

        uint256 balanceAfter = address(c).balance;

        // After withdrawAll, the contract balance should be zero
        assertTrue(balanceAfter == 0, "Balance after withdrawAll should be zero");
    }
}

