pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        value = bound(value, 0, address(c).balance);
        vm.assume(target != address(0) && target != address(c));
        vm.assume(data.length == 0);

        uint256 beforeOwnerBalance = address(c.owner()).balance;

        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value, data));

        if (!success) {
            // If sendMoney reverts, the reference should not have reverted because send does not revert
            assertTrue(false, "sendMoney should not revert in reference");
        } else {
            uint256 afterOwnerBalance = address(c.owner()).balance;
            assertTrue(afterOwnerBalance == beforeOwnerBalance + value, "Owner balance should increase by value");
        }
    }
}

