pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Bound value to avoid overflow and excessive gas, and ensure target is not zero to avoid stuck ether
        vm.assume(target != address(0));
        vm.assume(value <= address(c).balance);
        // Record depositsCount before
        uint256 before = c.depositsCount();
        // Call provideSendMoney; it might revert if send fails
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        // The rule: if the call succeeded, depositsCount must have increased by exactly 1; if it failed, depositsCount unchanged
        if (success) {
            assertTrue(c.depositsCount() == before + 1);
        } else {
            assertTrue(c.depositsCount() == before);
        }
    }
}

