import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Assume the owner calls sendMoney
        vm.assume(value > 0); // Only meaningful when value > 0
        vm.assume(target != address(0)); // Avoid revert due to address(0) in reference
        // Record balance before
        uint256 balanceBefore = address(c).balance;
        // Send value to contract first to ensure sufficient balance
        vm.deal(address(c), value);
        // Call sendMoney
        c.sendMoney(target, value, data);
        uint256 balanceAfter = address(c).balance;
        // The reference decreases balance by value; buggy version decreases by 0
        // So the difference is value
        assertTrue(balanceBefore + value - balanceAfter == value);
    }
}
